535	                        .header("X-Actor-Id", actor).header("X-Approval-Role", role)
536	                        .contentType(MediaType.APPLICATION_JSON)
537	                        .content("{\"commandKey\":\"" + commandKey + "\"}"))
538	                .andExpect(status().is(expected));
539	    }
540	
541	    private void recall(String batchKey, String actor, String reason, String commandKey, int expected)
542	            throws Exception {
543	        mockMvc.perform(post("/api/batches/" + batchKey + "/recall")
544	                        .header("X-Actor-Id", actor)
545	                        .contentType(MediaType.APPLICATION_JSON)
546	                        .content("{\"commandKey\":\"" + commandKey + "\",\"reason\":\"" + reason + "\"}"))
547	                .andExpect(status().is(expected));
548	    }
549	
550	    private String currentStatus(String batchKey) throws Exception {
551	        MvcResult result = mockMvc.perform(get("/api/batches/" + batchKey + "/history"))
552	                .andExpect(status().isOk()).andReturn();
553	        return objectMapper.readTree(result.getResponse().getContentAsString())
554	                .path("batch").path("status").asText();
555	    }
556	
557	    private List<String> availableKeys() throws Exception {
558	        MvcResult result = mockMvc.perform(get("/api/batches/available"))
559	                .andExpect(status().isOk()).andReturn();
560	        JsonNode array = objectMapper.readTree(result.getResponse().getContentAsString());
561	        List<String> keys = new ArrayList<>();
562	        array.forEach(n -> keys.add(n.path("batchKey").asText()));
563	        return keys;
564	    }
565	
566	    private int callStatus(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder req) {
567	        try {
568	            return mockMvc.perform(req).andReturn().getResponse().getStatus();
569	        } catch (Exception e) {
570	            throw new RuntimeException(e);
571	        }
572	    }
573	
574	    @SafeVarargs
575	    private List<Future<Integer>> runConcurrent(Callable<Integer>... tasks) throws Exception {
576	        ExecutorService pool = Executors.newFixedThreadPool(tasks.length);
577	        CyclicBarrier barrier = new CyclicBarrier(tasks.length);
578	        List<Future<Integer>> futures = new ArrayList<>();
579	        for (Callable<Integer> task : tasks) {
580	            futures.add(pool.submit(() -> {
581	                barrier.await(10, TimeUnit.SECONDS);
582	                return task.call();
583	            }));
584	        }
585	        pool.shutdown();
586	        assertTrue(pool.awaitTermination(30, TimeUnit.SECONDS));
587	        return futures;
588	    }
