    // ---------- 成分版本主流程 ----------

    @Test
    void reviseComposition_appendsImmutableVersions_andNormalizesOrder() throws Exception {
        String key = createBatch(BigDecimal.TEN, List.of("MILK", "GLUTEN"), "LOW");

