    // ---------- 召回与级别约束 ----------

    @Test
    void recallSource_descendantsCannotLowerSegregationLevel() throws Exception {
        // target 合入 s1（LOW），随后 s1 被召回；target 作为后代修订不得降低级别
        String target = createBatch(new BigDecimal("10"), List.of(), "NONE");
