input.old_string:
/**
 * 沿拆分血缘（子→父）与合批血缘（来源→目标容器）向上，是否存在任一被直接召回的祖先。
 */
boolean hasRecalledAncestor(String batchKey) {
    Map<String, String> splitParent = new HashMap<>();
    for (BatchRepository.LineageRow row : repo.findAllLineage()) {
        splitParent.put(row.childKey(), row.parentKey());
    }
    Map<String, String> mergeTarget = new HashMap<>();
    for (BatchRepository.MergeLineageRow row : repo.findAllMergeLineage()) {
        mergeTarget.put(row.sourceKey(), row.targetKey());
    }
    Set<String> recalled = new HashSet<>(repo.findRecalledKeys());
    Set<String> visited = new HashSet<>();
    List<String> frontier = new ArrayList<>();
    addParents(batchKey, splitParent, mergeTarget, frontier);
    while (!frontier.isEmpty()) {
        String current = frontier.remove(frontier.size() - 1);
        if (!visited.add(current)) {
            continue;
        }
        if (recalled.contains(current)) {
            return true;
        }
        addParents(current, splitParent, mergeTarget, frontier);
    }
    return false;
}

private void addParents(String key, Map<String, String> splitParent,
                        Map<String, String> mergeTarget, List<String> frontier) {
    String p = splitParent.get(key);
    if (p != null) {
        frontier.add(p);
    }
    String t = mergeTarget.get(key);
    if (t != null) {
        frontier.add(t);
    }
}

